// Helper to check if a node matches files changed in a commit
const isNodeInCommit = useCallback((nodeId: string, nodeLabel: string, nodeMetadata: any, filesChanged: string[]) => {
  if (!filesChanged) return false;
  return filesChanged.some(f => {
    const cleanF = f.replace(/\\/g, '/').toLowerCase();
    const cleanNodeId = nodeId.replace(/\\/g, '/').toLowerCase();
    const cleanPath = ((nodeMetadata.file_path as string) ?? (nodeMetadata.path as string) ?? '').replace(/\\/g, '/').toLowerCase();
    const cleanLabel = nodeLabel.toLowerCase();
    return cleanNodeId.endsWith(cleanF) || cleanF.endsWith(cleanNodeId) || cleanPath.endsWith(cleanF) || cleanF.endsWith(cleanPath) || cleanF.split('/').pop() === cleanLabel;
  });
}, []);

// Controlled nodes/edges synchronizer
// Only updates controlled states when raw graph arrays, toggles, or layout levels change.
// This completely eliminates loops because dragging nodes does not recalculate initialGraph.
useEffect(() => {
  let finalNodes = initialGraph.nodes;
  let finalEdges = initialGraph.edges;

  if (selectedCommitSha && gitActivity?.recentCommits) {
    const commit = gitActivity.recentCommits.find(c => c.sha === selectedCommitSha);
    if (commit && commit.filesChanged) {
      finalNodes = initialGraph.nodes.map((n: any) => {
        const matched = isNodeInCommit(n.id, n.data?.label || '', n.data?.metadata || {}, commit.filesChanged);
        return {
          ...n,
          style: {
            ...n.style,
            transition: 'all 0.25s ease',
            opacity: matched ? 1.0 : 0.15,
          },
          data: {
            ...n.data,
            highlighted: matched,
            dimmed: !matched,
            opacity: matched ? 1.0 : 0.15,
          }
        };
      });
      finalEdges = initialGraph.edges.map((e: any) => {
        const srcMatched = isNodeInCommit(e.source, '', {}, commit.filesChanged);
        const tgtMatched = isNodeInCommit(e.target, '', {}, commit.filesChanged);
        const matched = srcMatched || tgtMatched;
        return {
          ...e,
          style: {
            ...e.style,
            transition: 'all 0.25s ease',
            opacity: matched ? 1.0 : 0.15,
          }
        };
      });
    }
  } else if (searchQuery.trim()) {
    const q = searchQuery.toLowerCase().trim();
    finalNodes = initialGraph.nodes.map((n: any) => {
      const matched = (n.data?.label || '').toLowerCase().includes(q) || (n.id || '').toLowerCase().includes(q);
      return {
        ...n,
        style: {
          ...n.style,
          transition: 'all 0.25s ease',
          opacity: matched ? 1.0 : 0.15,
        },
        data: {
          ...n.data,
          highlighted: matched,
          dimmed: !matched,
          opacity: matched ? 1.0 : 0.15,
        }
      };
    });
    finalEdges = initialGraph.edges.map((e: any) => {
      const srcMatched = (e.source || '').toLowerCase().includes(q);
      const tgtMatched = (e.target || '').toLowerCase().includes(q);
      const matched = srcMatched || tgtMatched;
      return {
        ...e,
        style: {
          ...e.style,
          transition: 'all 0.25s ease',
          opacity: matched ? 1.0 : 0.15,
        }
      };
    });
  }

  setNodes(finalNodes);
  setEdges(finalEdges);
}, [initialGraph, setNodes, setEdges, selectedCommitSha, gitActivity, searchQuery, isNodeInCommit]);

